PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE pvp_honor (
  realm       TEXT    NOT NULL,      -- 伺服器名稱（遊戲的寫法）
  name        TEXT    NOT NULL,      -- 角色名字「主名 次名」
  faction     TEXT    NOT NULL CHECK (faction IN ('Alliance', 'Horde')),
  cls         TEXT,                  -- 職業英文代號（MAGE…）
  lv          INTEGER,               -- 查到時的等級
  guild       TEXT,                  -- 公會名（查到時讀不到的留原本的）
  life_hk     INTEGER NOT NULL,      -- 總榮譽擊殺（遊戲觀察視窗 PvP 分頁的「總計」）
  today_hk    INTEGER,               -- 查到那天的榮譽擊殺（只有 seen_at 是台灣時間今天的才算「今天」）
  pvp_rank    INTEGER,               -- 軍銜（0＝沒有，1～14）
  rank_cur    INTEGER,               -- 軍銜進度：目前
  rank_next   INTEGER,               -- 軍銜進度：下一級要多少
  raw         TEXT,                  -- 遊戲給的 9 個數字（逗號分隔，十進位；其他幾個還不知道是什麼，先存著）
  seen_at     INTEGER NOT NULL,      -- 查到的時間（伺服器時間，unix 秒）
  reports     INTEGER NOT NULL DEFAULT 1,   -- 收過幾次（不同時間查到的）
  uploaded_at INTEGER NOT NULL,
  PRIMARY KEY (realm, name)
);
